<?php

namespace App\Http\Controllers\Api\V1\EmailMarketing;

use App\Http\Controllers\Controller;
use App\Services\EmailMarketing\CampaignSenderService;
use Illuminate\Http\{JsonResponse,Request};
use Illuminate\Support\Facades\{Crypt,DB};
use Illuminate\Support\Str;

class EmailMarketingController extends Controller
{
    public function dashboard(Request $r): JsonResponse { $e=$r->user()->empresa_id; return response()->json(['settings'=>$this->settings($e),'contacts'=>DB::table('email_marketing_contacts')->where('empresa_id',$e)->orderByDesc('id')->limit(500)->get(),'templates'=>DB::table('email_marketing_templates')->where('empresa_id',$e)->orderBy('nome')->get(),'campaigns'=>DB::table('email_marketing_campaigns')->where('empresa_id',$e)->orderByDesc('id')->limit(100)->get()]); }
    public function saveSettings(Request $r): JsonResponse { $d=$r->validate(['host'=>'required|string|max:255','port'=>'required|integer|min:1|max:65535','encryption'=>'nullable|in:tls,ssl','username'=>'nullable|string|max:255','password'=>'nullable|string|max:500','from_email'=>'required|email|max:180','from_name'=>'nullable|string|max:180','reply_to'=>'nullable|email|max:180','rate_per_minute'=>'required|integer|min:1|max:500','active'=>'required|boolean']); $e=$r->user()->empresa_id; $old=DB::table('email_marketing_settings')->where('empresa_id',$e)->first(); $payload=collect($d)->except(['username','password'])->all(); $payload['username_encrypted']=filled($d['username']??null)?Crypt::encryptString($d['username']):($old?->username_encrypted); $payload['password_encrypted']=filled($d['password']??null)?Crypt::encryptString($d['password']):($old?->password_encrypted); $payload['updated_at']=now(); DB::table('email_marketing_settings')->updateOrInsert(['empresa_id'=>$e],array_merge($payload,$old?[]:['created_at'=>now()])); return response()->json(['message'=>'Servidor de saída configurado.','settings'=>$this->settings($e)]); }
    public function saveContact(Request $r,?int $id=null): JsonResponse { $d=$r->validate(['email'=>'required|email|max:180','nome'=>'nullable|string|max:180','empresa'=>'nullable|string|max:180','cidade'=>'nullable|string|max:120','tags'=>'nullable|array','consentimento'=>'required|boolean','origem_consentimento'=>'required_if:consentimento,true|nullable|string|max:120','ativo'=>'required|boolean']); $e=$r->user()->empresa_id; $d['tags']=json_encode($d['tags']??[]); if($d['consentimento'])$d['consentimento_em']=now(); $d['updated_at']=now(); if($id){DB::table('email_marketing_contacts')->where('empresa_id',$e)->where('id',$id)->update($d);}else{DB::table('email_marketing_contacts')->insert(array_merge($d,['empresa_id'=>$e,'uuid'=>(string)Str::uuid(),'unsubscribe_token'=>hash('sha256',Str::random(64)),'created_at'=>now()]));} return response()->json(['message'=>'Contato salvo.']); }
    public function saveTemplate(Request $r,?int $id=null): JsonResponse { $d=$r->validate(['nome'=>'required|string|max:180','assunto'=>'required|string|max:240','html'=>'required|string|max:200000','ativo'=>'required|boolean']);$e=$r->user()->empresa_id;$d['updated_at']=now();if($id)DB::table('email_marketing_templates')->where('empresa_id',$e)->where('id',$id)->update($d);else DB::table('email_marketing_templates')->insert(array_merge($d,['empresa_id'=>$e,'uuid'=>(string)Str::uuid(),'created_at'=>now()]));return response()->json(['message'=>'Modelo salvo.']); }
    public function saveCampaign(Request $r): JsonResponse { $d=$r->validate(['nome'=>'required|string|max:180','assunto'=>'required|string|max:240','html'=>'required|string|max:200000','template_id'=>'nullable|integer','agendada_para'=>'nullable|date|after_or_equal:now']);$e=$r->user()->empresa_id;$id=DB::table('email_marketing_campaigns')->insertGetId(array_merge($d,['empresa_id'=>$e,'uuid'=>(string)Str::uuid(),'status'=>'rascunho','created_at'=>now(),'updated_at'=>now()]));return response()->json(['message'=>'Campanha criada.','id'=>$id],201); }
    public function queue(Request $r,int $id): JsonResponse { $e=$r->user()->empresa_id;$c=DB::table('email_marketing_campaigns')->where('empresa_id',$e)->where('id',$id)->firstOrFail();abort_unless($this->settingsRaw($e)?->active,422,'Configure e ative o servidor SMTP antes do envio.');$contacts=DB::table('email_marketing_contacts')->where('empresa_id',$e)->where('ativo',true)->where('consentimento',true)->whereNull('descadastrado_em')->pluck('id');foreach($contacts as $contactId)DB::table('email_marketing_messages')->updateOrInsert(['campaign_id'=>$c->id,'contact_id'=>$contactId],['status'=>'pendente','updated_at'=>now(),'created_at'=>now()]);DB::table('email_marketing_campaigns')->where('id',$c->id)->update(['status'=>'na_fila','total'=>$contacts->count(),'updated_at'=>now()]);return response()->json(['message'=>'Campanha adicionada à fila.','total'=>$contacts->count()]); }
    public function process(CampaignSenderService $sender): JsonResponse { return response()->json(['message'=>'Fila processada.','processados'=>$sender->processar()]); }
    public function unsubscribe(string $token): JsonResponse { $updated=DB::table('email_marketing_contacts')->where('unsubscribe_token',$token)->update(['ativo'=>false,'descadastrado_em'=>now(),'updated_at'=>now()]);return response()->json(['message'=>$updated?'Descadastro realizado com sucesso.':'Link de descadastro inválido.'], $updated?200:404); }
    private function settings(int $e): array { $s=$this->settingsRaw($e);return $s?['host'=>$s->host,'port'=>$s->port,'encryption'=>$s->encryption,'username'=>$s->username_encrypted?'••••••••':'','password'=>$s->password_encrypted?'••••••••':'','from_email'=>$s->from_email,'from_name'=>$s->from_name,'reply_to'=>$s->reply_to,'rate_per_minute'=>$s->rate_per_minute,'active'=>(bool)$s->active]:['host'=>'smtp.gmail.com','port'=>587,'encryption'=>'tls','username'=>'','password'=>'','from_email'=>'','from_name'=>'IntelbrasTech','reply_to'=>'','rate_per_minute'=>20,'active'=>false]; }
    private function settingsRaw(int $e): ?object { return DB::table('email_marketing_settings')->where('empresa_id',$e)->first(); }
}
